WITH d AS (SELECT * FROM debate_results WHERE panel_expected IS NOT NULL AND cardinality(panel_expected)>0 AND (created_at > now()-interval '30 days' OR id IN (SELECT debate_id FROM debate_judgments WHERE id IN (973,976,1150,1153,1163,1174,1176))) ORDER BY created_at LIMIT 50 OFFSET %OFF%),
P AS (SELECT '(\[AUDIT v21: DEBATE RULE VIOLATION REPORT -- [^\n]*?RESULT: UNCURED[^\n]*?\](?=\s*(?:\n|$|\\n))|\[AUDIT v21: ALTERNATE TRIED -- [^\n]*?\](?=\s*(?:\n|$|\\n))|\[AUDIT v21: CORRECTED RESULT[^\]]*\]|\[AUDIT v25: RECOMPUTED AFTER CURE -- [^\n]*?ORIGINAL: [^\n]*?; RECOMPUTED: [^;\n]*;|\[AUDIT v37: SEND-BACK APPLIED \([^)]*\) -- [^\n]*?; DERIVED: [^;\n]*;|(?:HELD|PARTIAL|BROKEN) \(recomputed by the engine; the judge wrote [A-Z]+\)|RESULT[ \t*_]*:[ \t*_]*(?:DEFENDER WINS|CHALLENGER WINS|UNDERDETERMINED)[^\n"\\]{0,200}|D[0-9]+ vs C[0-9]+[^\n\\]{0,300}?:[ \t*_]*CHALLENGER LINK BROKEN|TIE \(KB-0030\))' AS rx)
SELECT json_agg(json_build_object('r', json_build_object('id',d.id,'run_token',d.run_token,'created_at',d.created_at,'topic',left(d.topic,80),'panel_verdict',d.panel_verdict,'outcome',d.outcome,'panel_split',d.panel_split,'judged_by',d.judged_by,'underdetermined_seats',d.underdetermined_seats,'citation_block',d.citation_block,'panel_substitution',d.panel_substitution,'defender_engine',d.defender_engine,'defender_model',d.defender_model,'defender_profile',d.defender_profile,'challenger_engine',d.challenger_engine,'challenger_model',d.challenger_model,'challenger_profile',d.challenger_profile,'judge_model',d.judge_model,
 'drv_removed',(SELECT json_agg((e - 'verdict_raw') || jsonb_build_object('sql_rw', judgment_result_word(e->>'verdict_raw', e->>'seat', e->>'challenge_standing'), 'verdict_raw', (SELECT string_agg(regexp_replace(m[1], '^(\[AUDIT v21: DEBATE RULE VIOLATION REPORT -- .*; WHY: .{0,60}).*$', '\1]'), E'\n') FROM regexp_matches(coalesce(e->>'verdict_raw',''), P.rx, 'g') m))) FROM jsonb_array_elements(CASE WHEN jsonb_typeof(d.drv_removed)='array' THEN d.drv_removed ELSE '[]'::jsonb END) e)),
 'J',(SELECT json_agg(json_build_object('id',j.id,'judge_seat',j.judge_seat,'judge_api_model',j.judge_api_model,'verdict_tag',j.verdict_tag,'truncated',j.truncated,'drv_uncured',j.drv_uncured,'defense_standing',j.defense_standing,'challenge_standing',j.challenge_standing,'conceded_links',j.conceded_links,'challenger_conceded_links',j.challenger_conceded_links,'sql_rw',judgment_result_word(j.verdict_raw,j.judge_seat,j.challenge_standing),
   'verdict_raw',(SELECT string_agg(regexp_replace(m[1], '^(\[AUDIT v21: DEBATE RULE VIOLATION REPORT -- .*; WHY: .{0,60}).*$', '\1]'), E'\n') FROM regexp_matches(j.verdict_raw, P.rx, 'g') m)) ORDER BY j.id) FROM debate_judgments j WHERE j.debate_id=d.id))) x FROM d, P
